    /// <summary>The page with the headings font embedded (the token is in the address, not in the page).</summary>
    public static string Html(string token)
    {
        using var stream = typeof(GuiPage).Assembly.GetManifestResourceStream("gui.html")
            ?? throw new InvalidOperationException("The interface page is missing from the exe (gui.html).");
        using var reader = new StreamReader(stream, System.Text.Encoding.UTF8);
        var html = reader.ReadToEnd();
        return html.Replace("</head>", "<style>" + ReportWriter.FontFaceCss + "</style></head>", StringComparison.Ordinal);
    }
